import type { PolymorphicProps } from "@kobalte/core/polymorphic";
import * as SwitchPrimitive from "@kobalte/core/switch";
import type { JSX, ValidComponent } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";

import { omit } from "solid-js";

type SwitchRootProps<T extends ValidComponent = "div"> =
  & SwitchPrimitive.SwitchRootProps<T>
  & { class?: string | undefined };

const Switch = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, SwitchRootProps<T>>,
) => {
  const local = props as SwitchRootProps;
  const others = omit(local, "class");
  return <SwitchPrimitive.Root class={cn("peer", local.class)} {...others} />;
};

const SwitchDescription = SwitchPrimitive.Description;
const SwitchErrorMessage = SwitchPrimitive.ErrorMessage;

type SwitchControlProps = SwitchPrimitive.SwitchControlProps & {
  class?: string | undefined;
  children?: JSX.Element;
  size?: "sm" | "default";
  onClick?: JSX.EventHandlerUnion<HTMLElement, MouseEvent>;
};

const SwitchControl = <T extends ValidComponent = "input">(
  props: PolymorphicProps<T, SwitchControlProps>,
) => {
  const local = props as SwitchControlProps;
  const others = omit(local, "class", "children", "size", "onClick");
  return (
    <>
      <SwitchPrimitive.Input class="peer" />
      <SwitchPrimitive.Control
        data-slot="switch"
        data-size={local.size ?? "default"}
        onClick={(event: MouseEvent) => {
          const handler = local.onClick;
          const clickEvent = event as MouseEvent & {
            currentTarget: HTMLElement;
            target: Element;
          };
          if (typeof handler === "function") {
            handler(clickEvent);
          } else if (handler) {
            handler[0](handler[1], clickEvent);
          }
          if ((event.currentTarget as HTMLElement | null)?.closest("label")) {
            event.preventDefault();
          }
        }}
        class={cn(
          "data-checked:bg-primary bg-input peer-focus-visible:border-ring peer-focus-visible:ring-ring/50 data-invalid:ring-destructive/20 dark:data-invalid:ring-destructive/40 data-invalid:border-destructive dark:data-invalid:border-destructive/50 dark:bg-input/80 shrink-0 rounded-full border border-transparent peer-focus-visible:ring-3 data-invalid:ring-3 data-[size=default]:h-[18.4px] data-[size=default]:w-[32px] data-[size=sm]:h-[14px] data-[size=sm]:w-[24px] group/switch relative inline-flex items-center outline-none transition-all after:absolute after:-inset-x-3 after:-inset-y-2 data-disabled:cursor-not-allowed data-disabled:opacity-50",
          local.class,
        )}
        {...others}
      >
        {local.children}
      </SwitchPrimitive.Control>
    </>
  );
};

type SwitchThumbProps = SwitchPrimitive.SwitchThumbProps & {
  class?: string | undefined;
};

const SwitchThumb = <T extends ValidComponent = "div">(
  props: PolymorphicProps<T, SwitchThumbProps>,
) => {
  const local = props as SwitchThumbProps;
  const others = omit(local, "class");
  return (
    <SwitchPrimitive.Thumb
      data-slot="switch-thumb"
      class={cn(
        "bg-background dark:bg-foreground dark:data-checked:bg-primary-foreground rounded-full group-data-[size=default]/switch:size-4 group-data-[size=sm]/switch:size-3 data-checked:translate-x-[calc(100%-2px)] translate-x-0 pointer-events-none block ring-0 transition-transform",
        local.class,
      )}
      {...others}
    />
  );
};

type SwitchLabelProps = SwitchPrimitive.SwitchLabelProps & {
  class?: string | undefined;
};

const SwitchLabel = <T extends ValidComponent = "label">(
  props: PolymorphicProps<T, SwitchLabelProps>,
) => {
  const local = props as SwitchLabelProps;
  const others = omit(local, "class");
  return (
    <SwitchPrimitive.Label
      class={cn(
        "font-medium text-sm leading-none data-disabled:cursor-not-allowed data-disabled:opacity-70",
        local.class,
      )}
      {...others}
    />
  );
};

export {
  Switch,
  SwitchControl,
  SwitchDescription,
  SwitchErrorMessage,
  SwitchLabel,
  SwitchThumb,
};
